<?php require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json; charset=utf-8');$u=current_user();if(!$u||$u['rol']!=='paciente'){http_response_code(403);echo json_encode(['error'=>'Acceso denegado']);exit;}$mid=(int)($_GET['medico']??0);$fecha=$_GET['fecha']??'';$dt=DateTime::createFromFormat('!Y-m-d',$fecha);if(!$dt||$dt->format('Y-m-d')!==$fecha||$fecha<date('Y-m-d')||$fecha>date('Y-m-d',strtotime('+90 days'))){echo json_encode(['horas'=>[]]);exit;}$day=(int)$dt->format('N');$horarios=all('SELECT h.inicio,h.fin FROM horarios_medicos h JOIN medicos m ON m.id=h.medico_id JOIN usuarios u ON u.id=m.usuario_id WHERE h.medico_id=? AND h.dia_semana=? AND m.verificado=1 AND u.activo=1',[$mid,$day]);$ocupadas=all('SELECT hora FROM citas WHERE medico_id=? AND fecha=? AND estado="programada"',[$mid,$fecha]);$taken=array_column($ocupadas,'hora');$out=[];foreach($horarios as $h){$t=strtotime($fecha.' '.$h['inicio']);$end=strtotime($fecha.' '.$h['fin']);while($t+1800<=$end){$time=date('H:i:s',$t);if(!in_array($time,$taken,true)&&($fecha!==date('Y-m-d')||$time>date('H:i:s'))) $out[]=substr($time,0,5);$t+=1800;}}echo json_encode(['horas'=>array_values(array_unique($out))]);
